1	import http from 'node:http';
2	import { SnapshotError, Workspace, normalizeTags } from './workspace.js';
3	import { sameDocument } from './history.js';
4	import { reconcileSnapshots } from './reconcile.js';
5	
6	const MAX_BODY_BYTES = 1024 * 1024;
7	const ETAG_PATTERN = /^"[0-9a-f]{64}"$/u;
8	const ID_PATTERN = /^[a-z0-9][a-z0-9._-]*$/u;
9	const DOCUMENT_FIELDS = new Set(['id', 'title', 'body', 'tags']);
10	const BATCH_ACTIONS = new Set(['create', 'replace', 'delete', 'restore']);
11	const MAX_BATCH_OPERATIONS = 100;
12	const TAG_RULE_FIELDS = ['from', 'to'];
13	const MAX_TAG_RULES = 100;
14	
15	function compareCodePoints(a, b) {
16	  const left = Array.from(a, (char) => char.codePointAt(0));
17	  const right = Array.from(b, (char) => char.codePointAt(0));
18	  for (let i = 0; i < Math.min(left.length, right.length); i += 1) {
19	    if (left[i] !== right[i]) return left[i] - right[i];
20	  }
21	  return left.length - right.length;
22	}
23	
24	function sameTags(a, b) {
25	  return a.length === b.length && a.every((tag, i) => tag === b[i]);
26	}
27	
28	class HttpError extends Error {
29	  constructor(status, code, message, extra = {}) {
30	    super(message);
31	    this.name = 'HttpError';
32	    this.status = status;
33	    this.code = code;
34	    for (const [key, value] of Object.entries(extra)) this[key] = value;
35	  }
36	}
37	
38	function sendJson(res, status, payload, etag) {
39	  const headers = { 'content-type': 'application/json; charset=utf-8' };
40	  if (etag) headers.etag = etag;
41	  res.writeHead(status, headers);
42	  res.end(JSON.stringify(payload));
43	}
44	
45	async function readBody(req) {
46	  const declared = Number(req.headers['content-length']);
47	  if (Number.isFinite(declared) && declared > MAX_BODY_BYTES) {
48	    req.resume();
49	    throw new HttpError(413, 'PAYLOAD_TOO_LARGE', 'request body exceeds 1 MiB');
50	  }
51	  const chunks = [];
52	  let size = 0;
53	  for await (const chunk of req) {
54	    size += chunk.length;
55	    if (size > MAX_BODY_BYTES) {
56	      throw new HttpError(413, 'PAYLOAD_TOO_LARGE', 'request body exceeds 1 MiB');
57	    }
58	    chunks.push(chunk);
59	  }
60	  return Buffer.concat(chunks).toString('utf8');
61	}
62	
63	function parseJson(text) {
64	  try {
65	    return JSON.parse(text);
66	  } catch {
67	    throw new HttpError(400, 'INVALID_JSON', 'request body is not valid JSON');
68	  }
69	}
70	
71	function validateDocument(data) {
72	  if (!data || typeof data !== 'object' || Array.isArray(data)) {
73	    throw new HttpError(400, 'INVALID_DOCUMENT', 'document must be an object');
74	  }
75	  for (const key of Object.keys(data)) {
76	    if (!DOCUMENT_FIELDS.has(key)) {
77	      throw new HttpError(400, 'INVALID_DOCUMENT', `unknown document field: ${key}`);
78	    }
79	  }
80	  for (const key of ['id', 'title', 'body']) {
81	    if (typeof data[key] !== 'string' || !data[key].trim()) {
82	      throw new HttpError(400, 'INVALID_DOCUMENT', `${key} must be a non-empty string`);
83	    }
84	  }
85	  if (!ID_PATTERN.test(data.id)) {
86	    throw new HttpError(400, 'INVALID_DOCUMENT', 'id must be URL-safe lowercase text');
87	  }
88	  if (data.tags !== undefined && (!Array.isArray(data.tags) || data.tags.some((tag) => typeof tag !== 'string'))) {
89	    throw new HttpError(400, 'INVALID_DOCUMENT', 'tags must be an array of strings');
90	  }
91	  return { id: data.id, title: data.title, body: data.body, tags: data.tags ?? [] };
92	}
93	
94	// Validates the batch envelope and every operation, returning normalized
95	// `{ operations, dryRun }`. Structural problems (bad envelope shape, unknown
96	// type, wrong fields, missing id, non-string id) are INVALID_BATCH; document
97	// content problems follow the single-document rules (INVALID_DOCUMENT), and a
98	// revision that is not a positive integer is INVALID_REVISION.
99	function validateBatchRequest(data) {
100	  if (!data || typeof data !== 'object' || Array.isArray(data)) {
101	    throw new HttpError(400, 'INVALID_BATCH', 'batch body must be an object');
102	  }
103	  for (const key of Object.keys(data)) {
104	    if (key !== 'operations' && key !== 'dryRun') {
105	      throw new HttpError(400, 'INVALID_BATCH', `unknown batch field: ${key}`);
106	    }
107	  }
108	  if (!Array.isArray(data.operations)) {
109	    throw new HttpError(400, 'INVALID_BATCH', 'operations must be an array');
110	  }
111	  if (data.operations.length < 1 || data.operations.length > MAX_BATCH_OPERATIONS) {
112	    throw new HttpError(400, 'INVALID_BATCH', `operations must contain 1 to ${MAX_BATCH_OPERATIONS} items`);
113	  }
114	  const dryRun = data.dryRun === undefined ? false : data.dryRun;
115	  if (typeof dryRun !== 'boolean') {
116	    throw new HttpError(400, 'INVALID_BATCH', 'dryRun must be a boolean');
117	  }
118	
119	  const operations = data.operations.map((op, index) => {
120	    if (!op || typeof op !== 'object' || Array.isArray(op)) {
121	      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] must be an object`);
122	    }
123	    const type = op.type;
124	    if (typeof type !== 'string' || !BATCH_ACTIONS.has(type)) {
125	      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] has an unknown type`);
126	    }
127	    const expectedKeys = type === 'create' || type === 'replace'
128	      ? ['type', 'document']
129	      : type === 'delete'
130	        ? ['type', 'id']
131	        : ['type', 'id', 'revision'];
132	    const keys = Object.keys(op);
133	    if (keys.length !== expectedKeys.length || !expectedKeys.every((key) => keys.includes(key))) {
134	      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] has invalid fields for ${type}`);
135	    }
136	
137	    if (type === 'create' || type === 'replace') {
138	      if (!op.document || typeof op.document !== 'object' || Array.isArray(op.document)) {
139	        throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] document must be an object`);
140	      }
141	      return { type, document: validateDocument(op.document) };
142	    }
143	
144	    if (typeof op.id !== 'string') {
145	      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] id must be a string`);
146	    }
147	
148	    if (type === 'delete') {
149	      return { type, id: op.id };
150	    }
151	
152	    // restore: the envelope is structurally valid; the revision value itself
153	    // follows the single-document restore rules.
154	    if (op.revision === undefined) {
155	      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] restore requires a revision`);
156	    }
157	    if (!Number.isInteger(op.revision) || op.revision < 1) {
158	      throw new HttpError(400, 'INVALID_REVISION', `operations[${index}] revision must be a positive integer`);
159	    }
160	    return { type, id: op.id, revision: op.revision };
161	  });
162	
163	  // Every operation targets a distinct document id.
164	  const seen = new Set();
165	  for (const op of operations) {
166	    const id = op.type === 'create' || op.type === 'replace' ? op.document.id : op.id;
167	    if (seen.has(id)) {
168	      throw new HttpError(400, 'INVALID_BATCH', `duplicate target id in batch: ${id}`);
169	    }
170	    seen.add(id);
171	  }
172	
173	  return { operations, dryRun };
174	}
175	
176	// Counts current tag usage across the live documents. Deleted documents are
177	// absent from the workspace and therefore never counted; history is ignored.
178	function tagStats(workspace) {
179	  const counts = new Map();
180	  for (const document of workspace.list()) {
181	    for (const tag of document.tags) counts.set(tag, (counts.get(tag) ?? 0) + 1);
182	  }
183	  return [...counts.entries()]
184	    .map(([tag, count]) => ({ tag, count }))
185	    .sort((a, b) => compareCodePoints(a.tag, b.tag));
186	}
187	
188	// Validates the rewrite envelope and every rule, returning normalized
189	// `{ rules, dryRun }` as `[{ from, to }]` pairs of trimmed, lowercased names
190	// (`to` stays `null` for removals). Structural problems, empty normalized
191	// names, duplicate sources, and out-of-range rule counts are INVALID_TAG_RULES.
192	function validateTagRules(data) {
193	  if (!data || typeof data !== 'object' || Array.isArray(data)) {
194	    throw new HttpError(400, 'INVALID_TAG_RULES', 'rewrite body must be an object');
195	  }
196	  for (const key of Object.keys(data)) {
197	    if (key !== 'rules' && key !== 'dryRun') {
198	      throw new HttpError(400, 'INVALID_TAG_RULES', `unknown rewrite field: ${key}`);
199	    }
200	  }
201	  if (!Array.isArray(data.rules)) {
202	    throw new HttpError(400, 'INVALID_TAG_RULES', 'rules must be an array');
203	  }
204	  if (data.rules.length < 1 || data.rules.length > MAX_TAG_RULES) {
205	    throw new HttpError(400, 'INVALID_TAG_RULES', `rules must contain 1 to ${MAX_TAG_RULES} items`);
206	  }
207	  const dryRun = data.dryRun === undefined ? false : data.dryRun;
208	  if (typeof dryRun !== 'boolean') {
209	    throw new HttpError(400, 'INVALID_TAG_RULES', 'dryRun must be a boolean');
210	  }
211	
212	  const rules = data.rules.map((rule, index) => {
213	    if (!rule || typeof rule !== 'object' || Array.isArray(rule)) {
214	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}] must be an object`);
215	    }
216	    const keys = Object.keys(rule);
217	    if (keys.length !== TAG_RULE_FIELDS.length || !TAG_RULE_FIELDS.every((key) => keys.includes(key))) {
218	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}] must contain exactly from and to`);
219	    }
220	    if (typeof rule.from !== 'string') {
221	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}].from must be a string`);
222	    }
223	    if (typeof rule.to !== 'string' && rule.to !== null) {
224	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}].to must be a string or null`);
225	    }
226	    const from = rule.from.trim().toLowerCase();
227	    const to = rule.to === null ? null : rule.to.trim().toLowerCase();
228	    if (!from) {
229	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}].from must not be blank`);
230	    }
231	    if (to !== null && !to) {
232	      throw new HttpError(400, 'INVALID_TAG_RULES', `rules[${index}].to must not be blank`);
233	    }
234	    return { from, to };
235	  });
236	
237	  const seen = new Set();
238	  for (const { from } of rules) {
239	    if (seen.has(from)) {
240	      throw new HttpError(400, 'INVALID_TAG_RULES', `duplicate source tag after normalization: ${from}`);
241	    }
242	    seen.add(from);
243	  }
244	
245	  return { rules, dryRun };
246	}
247	
248	// Validates the reconcile envelope `{ base, incoming, dryRun? }`, where base
249	// and incoming are version-1 snapshot objects (strings are not accepted at
250	// this layer; malformed JSON is rejected earlier by the shared body parser).
251	// Snapshot contents themselves are validated by normalizeSnapshot via the
252	// reconcile core, which reports INVALID_SNAPSHOT.
253	function validateReconcileRequest(data) {
254	  if (!data || typeof data !== 'object' || Array.isArray(data)) {
255	    throw new HttpError(400, 'INVALID_OPTIONS', 'reconcile body must be an object');
256	  }
257	  for (const key of Object.keys(data)) {
258	    if (key !== 'base' && key !== 'incoming' && key !== 'dryRun') {
259	      throw new HttpError(400, 'INVALID_OPTIONS', `unknown reconcile field: ${key}`);
260	    }
261	  }
262	  if (!data.base || typeof data.base !== 'object' || Array.isArray(data.base)) {
263	    throw new HttpError(400, 'INVALID_OPTIONS', 'base must be a snapshot object');
264	  }
265	  if (!data.incoming || typeof data.incoming !== 'object' || Array.isArray(data.incoming)) {
266	    throw new HttpError(400, 'INVALID_OPTIONS', 'incoming must be a snapshot object');
267	  }
268	  const dryRun = data.dryRun === undefined ? false : data.dryRun;
269	  if (typeof dryRun !== 'boolean') {
270	    throw new HttpError(400, 'INVALID_OPTIONS', 'dryRun must be a boolean');
271	  }
272	  return { base: data.base, incoming: data.incoming, dryRun };
273	}
274	
275	// A document server holds one Workspace and, when a history store is supplied,
276	// a per-document revision ledger. Every committed change is persisted through
277	// `save(snapshot, historySnapshot)` before the in-memory state is swapped, so a
278	// failed save leaves memory, queries, history, and the original files
279	// untouched. Everything here is synchronous, so a commit is atomic with
280	// respect to other requests.
281	export function createDocumentServer({ workspace, save, history = null }) {
282	  let current = workspace;
283	  let ledger = history;
284	
285	  const currentEtag = () => `"${current.exportJSON().checksum}"`;
286	
287	  function requireIfMatch(req) {
288	    const value = req.headers['if-match'];
289	    if (value === undefined) {
290	      throw new HttpError(428, 'PRECONDITION_REQUIRED', 'write requests require an If-Match header');
291	    }
292	    if (!ETAG_PATTERN.test(value)) {
293	      throw new HttpError(400, 'INVALID_IF_MATCH', 'If-Match must be a double-quoted checksum');
294	    }
295	    if (value !== currentEtag()) {
296	      throw new HttpError(412, 'PRECONDITION_FAILED', 'If-Match checksum is stale');
297	    }
298	  }
299	
300	  function assertTitleFree(candidate, title) {
301	    const trimmed = title.trim();
302	    for (const existing of candidate.list()) {
303	      if (existing.title === trimmed) {
304	        throw new HttpError(409, 'CONFLICT', `title already in use: ${trimmed}`);
305	      }
306	    }
307	  }
308	
309	  // Builds the next state on a candidate workspace and lets `mutate` append to
310	  // the next ledger. The callback returns false to signal a content-preserving
311	  // write (normalized content unchanged): the request still succeeds, but no
312	  // revision is appended and nothing is persisted.
313	  function commit(mutate) {
314	    const candidate = new Workspace();
315	    for (const document of current.list()) candidate.add(document);
316	    const nextLedger = ledger ? ledger.clone() : null;
317	    const changed = mutate(candidate, nextLedger);
318	    if (changed === false) {
319	      return current.exportJSON();
320	    }
321	    const snapshot = candidate.exportJSON();
322	    save(snapshot, nextLedger ? nextLedger.exportJSON(snapshot.checksum) : null);
323	    current = candidate;
324	    ledger = nextLedger;
325	    return snapshot;
326	  }
327	
328	  // Applies every operation in one atomic step. Existence and restore-version
329	  // checks all run against the pre-commit state, so a batch is rejected whole
330	  // if any operation would fail. Title conflicts are checked against the final
331	  // projected set, making swaps and release-then-reuse independent of
332	  // operation order. Each actually-changed document appends one record; a
333	  // normalized-identical replace or restore appends nothing. Returns
334	  // `{ snapshot, changed }` without persisting when `dryRun` is true or the
335	  // batch is content-preserving.
336	  function commitBatch(operations, dryRun) {
337	    // Pre-commit state checks.
338	    for (const op of operations) {
339	      if (op.type === 'create') {
340	        if (current.get(op.document.id)) {
341	          throw new HttpError(409, 'CONFLICT', `document already exists: ${op.document.id}`);
342	        }
343	      } else if (op.type === 'replace') {
344	        if (!current.get(op.document.id)) {
345	          throw new HttpError(404, 'NOT_FOUND', `document not found: ${op.document.id}`);
346	        }
347	      } else if (op.type === 'delete') {
348	        if (!current.get(op.id)) {
349	          throw new HttpError(404, 'NOT_FOUND', `document not found: ${op.id}`);
350	        }
351	      } else if (op.type === 'restore') {
352	        if (!ledger) {
353	          throw new HttpError(404, 'NOT_FOUND', 'history is not enabled');
354	        }
355	        const chain = ledger.entries(op.id);
356	        if (!chain) {
357	          throw new HttpError(404, 'NOT_FOUND', `document never existed: ${op.id}`);
358	        }
359	        const target = ledger.entry(op.id, op.revision);
360	        if (!target) {
361	          throw new HttpError(404, 'NOT_FOUND', `unknown revision ${op.revision} for document ${op.id}`);
362	        }
363	        if (target.action === 'delete') {
364	          throw new HttpError(400, 'INVALID_REVISION', `revision ${op.revision} of document ${op.id} is a delete and cannot be restored`);
365	        }
366	      }
367	    }
368	
369	    const candidate = new Workspace();
370	    for (const document of current.list()) candidate.add(document);
371	    const nextLedger = ledger ? ledger.clone() : null;
372	
373	    let changed = false;
374	    for (const op of operations) {
375	      if (op.type === 'create') {
376	        candidate.add(op.document);
377	        if (nextLedger) nextLedger.record(op.document.id, 'create', candidate.get(op.document.id));
378	        changed = true;
379	      } else if (op.type === 'replace') {
380	        const before = current.get(op.document.id);
381	        candidate.remove(op.document.id);
382	        candidate.add(op.document);
383	        const stored = candidate.get(op.document.id);
384	        if (!sameDocument(before, stored)) {
385	          if (nextLedger) nextLedger.record(op.document.id, 'replace', stored);
386	          changed = true;
387	        }
388	      } else if (op.type === 'delete') {
389	        candidate.remove(op.id);
390	        if (nextLedger) nextLedger.record(op.id, 'delete', null);
391	        changed = true;
392	      } else if (op.type === 'restore') {
393	        const before = current.get(op.id);
394	        const target = ledger.entry(op.id, op.revision);
395	        candidate.remove(op.id);
396	        candidate.add(target.document);
397	        const stored = candidate.get(op.id);
398	        if (!before || !sameDocument(before, stored)) {
399	          nextLedger.record(op.id, 'restore', stored);
400	          changed = true;
401	        }
402	      }
403	    }
404	
405	    // Title conflicts are checked against the final projected set, so
406	    // operation order cannot make a swap or release-then-reuse fail.
407	    const titles = new Set();
408	    for (const document of candidate.list()) {
409	      if (titles.has(document.title)) {
410	        throw new HttpError(409, 'CONFLICT', `title conflict in batch: ${document.title}`);
411	      }
412	      titles.add(document.title);
413	    }
414	
415	    if (dryRun) {
416	      return { snapshot: candidate.exportJSON(), changed };
417	    }
418	    if (!changed) {
419	      return { snapshot: current.exportJSON(), changed: false };
420	    }
421	
422	    const snapshot = candidate.exportJSON();
423	    save(snapshot, nextLedger ? nextLedger.exportJSON(snapshot.checksum) : null);
424	    current = candidate;
425	    ledger = nextLedger;
426	    return { snapshot, changed: true };
427	  }
428	
429	  async function createDocument(req, res) {
430	    const text = await readBody(req);
431	    requireIfMatch(req);
432	    const document = validateDocument(parseJson(text));
433	    const snapshot = commit((candidate, nextLedger) => {
434	      if (candidate.get(document.id)) {
435	        throw new HttpError(409, 'CONFLICT', `document already exists: ${document.id}`);
436	      }
437	      assertTitleFree(candidate, document.title);
438	      candidate.add(document);
439	      if (nextLedger) nextLedger.record(document.id, 'create', candidate.get(document.id));
440	    });
441	    sendJson(res, 201, snapshot, `"${snapshot.checksum}"`);
442	  }
443	
444	  async function replaceDocument(req, res, id) {
445	    const text = await readBody(req);
446	    requireIfMatch(req);
447	    const document = validateDocument(parseJson(text));
448	    if (document.id !== id) {
449	      throw new HttpError(400, 'ID_MISMATCH', `path id ${id} does not match body id ${document.id}`);
450	    }
451	    if (!current.get(id)) {
452	      throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
453	    }
454	    const before = current.get(id);
455	    const snapshot = commit((candidate, nextLedger) => {
456	      candidate.remove(id);
457	      assertTitleFree(candidate, document.title);
458	      candidate.add(document);
459	      const stored = candidate.get(id);
460	      // A replace whose normalized content is identical succeeds without
461	      // consuming a revision or touching the files.
462	      if (sameDocument(before, stored)) return false;
463	      if (nextLedger) nextLedger.record(id, 'replace', stored);
464	      return true;
465	    });
466	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
467	  }
468	
469	  function deleteDocument(req, res, id) {
470	    requireIfMatch(req);
471	    if (!current.get(id)) {
472	      throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
473	    }
474	    const snapshot = commit((candidate, nextLedger) => {
475	      candidate.remove(id);
476	      if (nextLedger) nextLedger.record(id, 'delete', null);
477	    });
478	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
479	  }
480	
481	  function historyDocument(req, res, id) {
482	    if (!ledger) throw new HttpError(404, 'NOT_FOUND', `no route for GET /documents/${id}/history`);
483	    const entries = ledger.entries(id);
484	    if (!entries) throw new HttpError(404, 'NOT_FOUND', `document never existed: ${id}`);
485	    sendJson(res, 200, entries, currentEtag());
486	  }
487	
488	  async function restoreDocument(req, res, id) {
489	    if (!ledger) throw new HttpError(404, 'NOT_FOUND', `no route for POST /documents/${id}/restore`);
490	    const text = await readBody(req);
491	    requireIfMatch(req);
492	    let data;
493	    try {
494	      data = JSON.parse(text);
495	    } catch {
496	      throw new HttpError(400, 'INVALID_REVISION', 'request body must be an object containing only a positive integer revision');
497	    }
498	    if (!data || typeof data !== 'object' || Array.isArray(data)
499	      || Object.keys(data).length !== 1 || !Object.hasOwn(data, 'revision')
500	      || !Number.isInteger(data.revision) || data.revision < 1) {
501	      throw new HttpError(400, 'INVALID_REVISION', 'request body must be an object containing only a positive integer revision');
502	    }
503	    const chain = ledger.entries(id);
504	    if (!chain) throw new HttpError(404, 'NOT_FOUND', `document never existed: ${id}`);
505	    const target = ledger.entry(id, data.revision);
506	    if (!target) throw new HttpError(404, 'NOT_FOUND', `unknown revision ${data.revision} for document ${id}`);
507	    if (target.action === 'delete') {
508	      throw new HttpError(400, 'INVALID_REVISION', `revision ${data.revision} of document ${id} is a delete and cannot be restored`);
509	    }
510	    const before = current.get(id);
511	    const snapshot = commit((candidate, nextLedger) => {
512	      candidate.remove(id);
513	      assertTitleFree(candidate, target.document.title);
514	      candidate.add(target.document);
515	      const stored = candidate.get(id);
516	      // Restoring the already-current content succeeds without a new record.
517	      if (before && sameDocument(before, stored)) return false;
518	      nextLedger.record(id, 'restore', stored);
519	      return true;
520	    });
521	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
522	  }
523	
524	  async function batch(req, res) {
525	    const text = await readBody(req);
526	    requireIfMatch(req);
527	    const data = parseJson(text);
528	    const { operations, dryRun } = validateBatchRequest(data);
529	    const { snapshot } = commitBatch(operations, dryRun);
530	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
531	  }
532	
533	  function listTags(req, res) {
534	    sendJson(res, 200, tagStats(current), currentEtag());
535	  }
536	
537	  // Applies the tag rules to the pre-rewrite tag set of every document. Each
538	  // original tag is looked up once, so a rule result is never itself rewritten
539	  // (a→b then b→c moves the original `a` straight to `b`) and swaps resolve
540	  // because `to` names are carried independently of the source keys. Returns
541	  // `{ snapshot, changedIds }` without persisting when `dryRun` is true or the
542	  // rewrite leaves the tag set unchanged.
543	  function commitTagRewrite(rules, dryRun) {
544	    const mapping = new Map(rules.map((rule) => [rule.from, rule.to]));
545	
546	    // Every source must be used by at least one currently-live document.
547	    const used = new Set();
548	    for (const document of current.list()) {
549	      for (const tag of document.tags) used.add(tag);
550	    }
551	    for (const from of mapping.keys()) {
552	      if (!used.has(from)) throw new HttpError(404, 'TAG_NOT_FOUND', `tag not in use: ${from}`);
553	    }
554	
555	    const candidate = new Workspace();
556	    for (const document of current.list()) candidate.add(document);
557	    const nextLedger = ledger ? ledger.clone() : null;
558	
559	    const changedIds = [];
560	    for (const document of current.list()) {
561	      if (!document.tags.some((tag) => mapping.has(tag))) continue;
562	      // A null target removes the tag; mapped results are emitted as-is
563	      // without a second lookup, so new names are never chained further.
564	      const nextTags = normalizeTags(
565	        document.tags.flatMap((tag) => {
566	          if (!mapping.has(tag)) return [tag];
567	          const target = mapping.get(tag);
568	          return target === null ? [] : [target];
569	        }),
570	      );
571	      if (sameTags(document.tags, nextTags)) continue;
572	      const updated = { id: document.id, title: document.title, body: document.body, tags: nextTags };
573	      candidate.remove(document.id);
574	      candidate.add(updated);
575	      if (nextLedger) nextLedger.record(document.id, 'replace', candidate.get(document.id));
576	      changedIds.push(document.id);
577	    }
578	    changedIds.sort(compareCodePoints);
579	
580	    if (dryRun) {
581	      return { snapshot: candidate.exportJSON(), changedIds };
582	    }
583	    if (changedIds.length === 0) {
584	      // Tag set unchanged: report the current snapshot and no file/version work.
585	      return { snapshot: current.exportJSON(), changedIds: [] };
586	    }
587	
588	    const snapshot = candidate.exportJSON();
589	    save(snapshot, nextLedger ? nextLedger.exportJSON(snapshot.checksum) : null);
590	    current = candidate;
591	    ledger = nextLedger;
592	    return { snapshot, changedIds };
593	  }
594	
595	  async function rewriteTags(req, res) {
596	    const text = await readBody(req);
597	    requireIfMatch(req);
598	    const { rules, dryRun } = validateTagRules(parseJson(text));
599	    const { snapshot, changedIds } = commitTagRewrite(rules, dryRun);
600	    sendJson(res, 200, { snapshot, changedIds }, `"${snapshot.checksum}"`);
601	  }
602	
603	  // Merges an offline-edited incoming snapshot back against its base, keeping
604	  // non-conflicting online edits. The merge is computed against the current
605	  // live state; field/add/delete/title conflicts reject the whole request.
606	  // Each actually-changed document appends one ledger record (create for new
607	  // or reappearing ids, replace for edits, delete for removals), continuing
608	  // that id's revision sequence. Returns `{ snapshot, changedIds }` without
609	  // persisting when `dryRun` is true or the merge leaves the content equal to
610	  // the current state.
611	  function commitReconcile(base, incoming, dryRun) {
612	    const currentSnapshot = current.exportJSON();
613	    const result = reconcileSnapshots(currentSnapshot, base, incoming);
614	    if (result.conflicts.length > 0) {
615	      throw new HttpError(409, 'RECONCILE_CONFLICT', 'reconcile conflicts detected', {
616	        conflicts: result.conflicts,
617	      });
618	    }
619	    if (result.snapshot.checksum === currentSnapshot.checksum) {
620	      return { snapshot: currentSnapshot, changedIds: [] };
621	    }
622	
623	    const candidate = new Workspace();
624	    for (const document of result.snapshot.documents) candidate.add(document);
625	    const nextLedger = ledger ? ledger.clone() : null;
626	    for (const id of result.changedIds) {
627	      if (!nextLedger) break;
628	      const stored = candidate.get(id);
629	      if (stored) {
630	        // A previously-deleted id that reappears continues its chain with a
631	        // create; a changed live document gets a replace.
632	        const action = current.get(id) ? 'replace' : 'create';
633	        nextLedger.record(id, action, stored);
634	      } else {
635	        nextLedger.record(id, 'delete', null);
636	      }
637	    }
638	
639	    if (dryRun) {
640	      return { snapshot: candidate.exportJSON(), changedIds: result.changedIds };
641	    }
642	
643	    const snapshot = candidate.exportJSON();
644	    save(snapshot, nextLedger ? nextLedger.exportJSON(snapshot.checksum) : null);
645	    current = candidate;
646	    ledger = nextLedger;
647	    return { snapshot, changedIds: result.changedIds };
648	  }
649	
650	  async function reconcile(req, res) {
651	    const text = await readBody(req);
652	    requireIfMatch(req);
653	    const { base, incoming, dryRun } = validateReconcileRequest(parseJson(text));
654	    try {
655	      const snapshot = commitReconcile(base, incoming, dryRun).snapshot;
656	      sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
657	    } catch (error) {
658	      // Both snapshots must pass the existing validation; surface those
659	      // failures as INVALID_SNAPSHOT rather than an internal error. Save
660	      // failures keep their 500/IO_ERROR semantics.
661	      if (error instanceof SnapshotError && error.code === 'INVALID_SNAPSHOT') {
662	        throw new HttpError(400, 'INVALID_SNAPSHOT', error.message);
663	      }
664	      throw error;
665	    }
666	  }
667	
668	  async function handle(req, res) {
669	    const url = new URL(req.url, 'http://127.0.0.1');
670	    const segments = url.pathname.split('/').filter(Boolean).map(decodeURIComponent);
671	    const [resource, id, relation] = segments;
672	
673	    if (resource === 'documents' && segments.length === 1) {
674	      if (req.method === 'GET') {
675	        sendJson(res, 200, current.list(), currentEtag());
676	        return;
677	      }
678	      if (req.method === 'POST') {
679	        await createDocument(req, res);
680	        return;
681	      }
682	    } else if (resource === 'documents' && segments.length === 2) {
683	      if (req.method === 'GET') {
684	        const document = current.get(id);
685	        if (!document) throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
686	        sendJson(res, 200, document, currentEtag());
687	        return;
688	      }
689	      if (req.method === 'PUT') {
690	        await replaceDocument(req, res, id);
691	        return;
692	      }
693	      if (req.method === 'DELETE') {
694	        deleteDocument(req, res, id);
695	        return;
696	      }
697	    } else if (resource === 'documents' && segments.length === 3 && relation === 'links' && req.method === 'GET') {
698	      const links = current.links(id);
699	      if (!links) throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
700	      sendJson(res, 200, links, currentEtag());
701	      return;
702	    } else if (resource === 'documents' && segments.length === 3 && relation === 'history' && req.method === 'GET') {
703	      historyDocument(req, res, id);
704	      return;
705	    } else if (resource === 'documents' && segments.length === 3 && relation === 'restore' && req.method === 'POST') {
706	      await restoreDocument(req, res, id);
707	      return;
708	    } else if (resource === 'batch' && segments.length === 1 && req.method === 'POST') {
709	      await batch(req, res);
710	      return;
711	    } else if (resource === 'tags' && segments.length === 1 && req.method === 'GET') {
712	      listTags(req, res);
713	      return;
714	    } else if (resource === 'tags' && segments.length === 2 && id === 'rewrite' && req.method === 'POST') {
715	      await rewriteTags(req, res);
716	      return;
717	    } else if (resource === 'snapshots' && segments.length === 2 && id === 'reconcile' && req.method === 'POST') {
718	      await reconcile(req, res);
719	      return;
720	    } else if (resource === 'search' && segments.length === 1 && req.method === 'GET') {
721	      sendJson(res, 200, current.search(url.searchParams.get('q') ?? ''), currentEtag());
722	      return;
723	    }
724	    throw new HttpError(404, 'NOT_FOUND', `no route for ${req.method} ${url.pathname}`);
725	  }
726	
727	  const server = http.createServer((req, res) => {
728	    handle(req, res).catch((error) => {
729	      if (res.headersSent) {
730	        res.destroy(error);
731	        return;
732	      }
733	      const status = error instanceof HttpError ? error.status : 500;
734	      const code = error instanceof HttpError ? error.code
735	        : error instanceof SnapshotError ? error.code
736	          : 'INTERNAL_ERROR';
737	      const payload = { code, message: error.message };
738	      if (Array.isArray(error.conflicts)) payload.conflicts = error.conflicts;
739	      sendJson(res, status, payload);
740	    });
741	  });
742	  return server;
743	}
