57	async function startServerFailure(args, { cwd } = {}) {
58	  const child = spawn(process.execPath, [CLI, 'serve', ...args], { cwd, stdio: ['ignore', 'pipe', 'pipe'] });
59	  let stdout = '';
60	  let stderr = '';
61	  child.stdout.on('data', (chunk) => { stdout += chunk; });
62	  child.stderr.on('data', (chunk) => { stderr += chunk; });
63	  const status = await new Promise((resolve) => child.on('exit', resolve));
64	  return { status, stdout, stderr };
65	}
