67	async function request(base, method, route, { body, rawBody, headers = {} } = {}) {
68	  const response = await fetch(`${base}${route}`, {
69	    method,
70	    headers: {
71	      ...(body !== undefined || rawBody !== undefined ? { 'content-type': 'application/json' } : {}),
72	      ...headers,
73	    },
74	    body: rawBody ?? (body !== undefined ? JSON.stringify(body) : undefined),
75	  });
76	  const text = await response.text();
77	  return {
78	    status: response.status,
79	    etag: response.headers.get('etag'),
80	    body: text ? JSON.parse(text) : null,
81	  };
82	}
