    const stale = await request(server.url, 'POST', '/snapshots/reconcile', {
      body: { base, incoming },
      headers: { 'if-match': `"${'0'.repeat(64)}"` },
    });
    assert.equal(stale.status, 412);
    assert.equal(stale.body.code, 'PRECONDITION_FAILED');
  } finally {
    await server.stop();
  }
});

