input.command:
node --check src/server.js && node -e '
const { spawn } = require("node:child_process");
const fs = require("node:fs"), os = require("node:os"), path = require("node:path");
const cwd = fs.mkdtempSync(path.join(os.tmpdir(), "probe-"));
const srv = spawn(process.execPath, ["src/cli.js", "serve", path.join(cwd, "s.json"), "--port", "0", "--history", path.join(cwd, "h.json")], { stdio: ["ignore","pipe","ignore"] });
let out = "";
srv.stdout.on("data", d => out += d);
setTimeout(async () => {
  const { port } = JSON.parse(out.split("\n")[0]);
  const base = `http://127.0.0.1:${port}`;
  const etag = (await fetch(base + "/documents")).headers.get("etag");
  const send = (buf) => fetch(base + "/documents", { method: "POST", headers: { "content-type":"application/json", "if-match": etag }, body: buf }).then(async r => ({ s: r.status, c: (await r.json()).code }));
  const cases = {
    lone: Buffer.from([123,34,105,100,34,58,34,97,34,44,34,116,105,116,108,101,34,58,34,0x80,34,125]),
    overlongNull: Buffer.from("{\"id\":\"a\",\"title\":\"x\\u0000y\"}".replace(/\\u0000/, "PLACEHOLDER"), "utf8"),
  };
  console.log("lone-continuation:", JSON.stringify(await send(cases.lone)));
  // emoji + Chinese round trip
  const ok = Buffer.from(JSON.stringify({id:"a", title:"中文😀", body:"b", tags:[]}),"utf8");
  const r1 = await send(ok);
  console.log("valid multibyte:", JSON.stringify(r1));
  const doc = await (await fetch(base+"/documents/a")).json();
  console.log("stored title:", doc.title);
  srv.kill("SIGKILL");
}, 300);
'

